-- Ledger status becomes a list people can add to (ledger_statuses) instead of a fixed enum.
-- 'confirmed' and 'review' stay built in and protected; the two views that read
-- transactions.status are dropped and recreated unchanged around the column change.
CREATE TABLE "ledger_statuses" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "ledger_statuses_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"name" text NOT NULL,
	"sort_order" integer DEFAULT 0 NOT NULL,
	CONSTRAINT "ledger_statuses_name_unique" UNIQUE("name")
);
--> statement-breakpoint
ALTER TABLE "ledger_statuses" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
INSERT INTO "ledger_statuses" ("name", "sort_order") VALUES ('confirmed', 0), ('review', 1);--> statement-breakpoint

CREATE OR REPLACE FUNCTION public.protect_builtin_ledger_status() RETURNS trigger
LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  IF OLD.name IN ('confirmed', 'review') AND (TG_OP = 'DELETE' OR NEW.name <> OLD.name) THEN
    RAISE EXCEPTION 'The statuses "confirmed" and "review" are built in and cannot be renamed or deleted.';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $$;--> statement-breakpoint
CREATE TRIGGER ledger_statuses_protect BEFORE UPDATE OR DELETE ON public.ledger_statuses
  FOR EACH ROW EXECUTE FUNCTION public.protect_builtin_ledger_status();--> statement-breakpoint

DROP VIEW public.v_monthly_pnl;--> statement-breakpoint
DROP VIEW public.v_pnl_lines;--> statement-breakpoint
ALTER TABLE "transactions" ALTER COLUMN "status" DROP DEFAULT;--> statement-breakpoint
ALTER TABLE "transactions" ALTER COLUMN "status" SET DATA TYPE text USING "status"::text;--> statement-breakpoint
ALTER TABLE "transactions" ALTER COLUMN "status" SET DEFAULT 'confirmed';--> statement-breakpoint
ALTER TABLE "transactions" ADD CONSTRAINT "transactions_status_ledger_statuses_name_fk" FOREIGN KEY ("status") REFERENCES "public"."ledger_statuses"("name") ON DELETE no action ON UPDATE cascade;--> statement-breakpoint
DROP TYPE "public"."record_status";--> statement-breakpoint

CREATE VIEW public.v_pnl_lines WITH (security_invoker = true) AS
SELECT
  t.id AS transaction_id, t.entity_id, t.period, t.txn_date, t.type, t.status,
  t.service_line, t.category_id, c.name AS category, c.pnl_group, c.kind,
  t.amount_eur,
  CASE WHEN t.type::text IN ('income', 'refund') THEN t.amount_eur ELSE -t.amount_eur END
    AS signed_eur
FROM public.transactions t
JOIN public.categories c ON c.id = t.category_id
WHERE t.type::text IN ('income', 'expense', 'refund', 'reversal')
  AND t.counts_in IN ('pnl_and_cash', 'pnl_only');--> statement-breakpoint

CREATE VIEW public.v_monthly_pnl WITH (security_invoker = true) AS
SELECT entity_id, period, pnl_group, kind,
  sum(signed_eur) AS amount_eur,
  sum(CASE WHEN status = 'review' THEN signed_eur ELSE 0 END) AS review_eur,
  count(*) AS line_count
FROM public.v_pnl_lines
GROUP BY entity_id, period, pnl_group, kind;
